<?php

declare(strict_types=1);

namespace RefactorCircus\Ringside;

use RefactorCircus\Ringside\Render\HookWriter;
use RefactorCircus\Ringside\Render\ManagedBlock;
use RefactorCircus\Ringside\Render\SkillRenderer;
use RefactorCircus\Ringside\Render\Template;
use RefactorCircus\Ringside\Specs\SpecRepository;
use RefactorCircus\Ringside\Standards\Resolution;
use RefactorCircus\Ringside\Standards\StandardsResolver;

/**
 * Index + skills + subagent + hooks + managed block. Writes nothing when the
 * fingerprint is unchanged and every generated file is still in place.
 */
final class Sync
{
    public function __construct(private readonly StandardsResolver $resolver = new StandardsResolver) {}

    public function run(Project $project, bool $force = false): SyncResult
    {
        $resolution = $this->resolver->resolve($project);
        $indexPath = self::indexPath($project);

        if (! $force && $this->upToDate($project, $resolution)) {
            return new SyncResult($resolution, []);
        }

        $written = [];

        if ($project->write($indexPath, $resolution->toYaml())) {
            $written[] = $indexPath;
        }

        if ($project->write(self::summaryPath($project), self::summary($project, $resolution))) {
            $written[] = self::summaryPath($project);
        }

        $written = [...$written, ...(new SkillRenderer)->render($project, $resolution)];

        if ((new HookWriter)->write($project)) {
            $written[] = HookWriter::FILE;
        }

        return new SyncResult($resolution, [...$written, ...(new ManagedBlock)->write($project)]);
    }

    public function upToDate(Project $project, Resolution $resolution): bool
    {
        if (Resolution::storedFingerprint($project->read(self::indexPath($project))) !== $resolution->fingerprint) {
            return false;
        }

        return $project->exists(self::summaryPath($project)) && $project->exists('.claude/agents/ring-master-implementer.md');
    }

    public static function indexPath(Project $project): string
    {
        return $project->agentPath('standards.index.yml');
    }

    public static function summaryPath(Project $project): string
    {
        return $project->agentPath('standards.summary.md');
    }

    /**
     * The SessionStart hook prints this verbatim, so it stays well under 200 tokens.
     */
    public static function summary(Project $project, Resolution $resolution): string
    {
        $categories = array_map(
            static fn (string $category, array $standards): string => $category.' ('.count($standards).')',
            array_keys($resolution->byCategory()),
            $resolution->byCategory(),
        );

        $app = Template::boardApp($project);

        return '# generated by ringside; do not edit'."\n"
            .($app === null ? '' : '# ring-master-app: '.$app."\n")
            .'ringside: '.count($resolution->standards).' standards ['.implode(', ', $categories).'], index '.self::indexPath($project).".\n"
            ."Workflow: /ring-master-shape-spec -> /ring-master-write-spec -> /ring-master-create-tasks -> /ring-master-implement -> /ring-master-verify-spec.\n"
            .'Done means `'.$project->config->string('commands.verify').'` passes. Specs live in '.(new SpecRepository)->dir($project)."/ of each job's worktree (`ringside spec path <id>` finds one).\n";
    }
}
